const update = $json;

const callback = update.callback_query || null;
const isCallback = !!callback;

if (!isCallback && (update.message?.from?.is_bot || update.edited_message?.from?.is_bot)) {
  return [];
}

const msg = isCallback
  ? callback.message
  : (update.message || update.edited_message || update);

const callbackData = callback?.data || '';
const rawText = isCallback ? '' : (msg.text || msg.caption || '');

const chatId = isCallback ? callback.message?.chat?.id : msg.chat?.id;
const userId = isCallback ? callback.from?.id : msg.from?.id;

if (!chatId) return [];

const fs = require('fs');
const SESSION_FILE = '/tmp/contract_bot_sessions.json';
const staticData = $getWorkflowStaticData('global');

function readFileSessions() {
  try {
    return JSON.parse(fs.readFileSync(SESSION_FILE, 'utf8'));
  } catch (e) {
    return {};
  }
}

function writeFileSessions(s) {
  try {
    fs.writeFileSync(SESSION_FILE, JSON.stringify(s), 'utf8');
  } catch (e) {}
}

if (!staticData.sessions) staticData.sessions = {};

const sessions = {
  ...readFileSessions(),
  ...staticData.sessions
};

const keys = [String(chatId), userId ? `user:${userId}` : null].filter(Boolean);

function getSession() {
  for (const k of keys) {
    if (sessions[k] && Object.keys(sessions[k]).length) {
      return sessions[k];
    }
  }
  return {};
}

function saveSession(sess) {
  for (const k of keys) {
    sessions[k] = sess;
  }
  staticData.sessions = sessions;
  writeFileSessions(sessions);
}

function clearSession() {
  for (const k of keys) {
    delete sessions[k];
  }
  staticData.sessions = sessions;
  writeFileSessions(sessions);
}

let session = getSession();

const doc = !isCallback ? (msg.document || null) : null;
const photos = !isCallback ? (msg.photo || []) : [];

let inputType = 'text';
let fileId = null;
let fileName = null;
let mimeType = null;

if (doc) {
  inputType = 'file';
  fileId = doc.file_id;
  fileName = doc.file_name || null;
  mimeType = doc.mime_type || null;
} else if (photos.length) {
  inputType = 'file';
  fileId = photos[photos.length - 1].file_id;
  fileName = 'photo.jpg';
  mimeType = 'image/jpeg';
}

const BASE = {
  template_01_id: 'YOUR_TEMPLATE_01_DOC_ID',
  template_02_id: 'YOUR_TEMPLATE_02_DOC_ID',
  contract_type_labels: {
    '01': 'Договор покупателя',
    '02': 'Договор поставщика'
  },
  defaults: {
    payment_terms: 'Оплата за Товар осуществляется на условиях 100% предоплаты путём банковского перечисления на расчётный счёт Продавца',
    delivery_term: '10 (десять) календарных дней с момента получения предоплаты по согласованному Счету.',
    penalty_rate: '0,1%',
    default_amount: '2500000',
    delivery_conditions: 'Поставка осуществляется на условиях, согласованных Сторонами.'
  }
};

function uniqJoin(values) {
  const out = [];
  const seen = new Set();

  for (const value of values) {
    const s = String(value || '').trim();
    if (!s || seen.has(s)) continue;
    seen.add(s);
    out.push(s);
  }

  return out.join('\n');
}

function findValue(sourceText, patterns) {
  for (const pattern of patterns) {
    const m = String(sourceText || '').match(pattern);
    if (m && m[1]) return m[1].trim();
  }
  return null;
}

function parseContractType(sourceText) {
  let value = findValue(sourceText, [
    /(?:тип\s*договора|договор|договора|шаблон)\s*[:=№#\-–—]?\s*(01|02|1|2|покупател[ья]|поставщик[а]?)/i,
    /\b(01|02)\b/i
  ]);

  if (!value) return null;

  value = String(value).toLowerCase().trim();

  if (value === '1' || /покупател/.test(value)) return '01';
  if (value === '2' || /поставщик/.test(value)) return '02';

  return ['01', '02'].includes(value) ? value : null;
}

function parseOutputFormat(sourceText) {
  let value = findValue(sourceText, [
    /(?:формат|файл|выдать)\s*[:=\-–—]?\s*(pdf|docx|doc|word)/i,
    /\b(pdf|docx|doc|word)\b/i
  ]);

  if (!value) return null;

  value = String(value).toLowerCase().trim();

  if (value === 'word' || value === 'doc') return 'docx';

  return ['pdf', 'docx'].includes(value) ? value : null;
}

function parseContractNumber(sourceText) {
  const s = String(sourceText || '').trim();
  const lower = s.toLowerCase();

  // Даты словами не могут быть номером договора.
  const isDateWord = /^(?:вчера|сегодня|завтра|вчерашн(?:ее|его)\s+числ[ао]|сегодняшн(?:ее|его)\s+числ[ао]|завтрашн(?:ее|его)\s+числ[ао])$/iu.test(lower);
  if (isDateWord) return null;

  // Если пользователь явно написал "номер договора", забираем всё до конца строки.
  const explicit = s.match(/(?:номер\s+договора|№\s*договора|договор\s*(?:№|N|No))\s*[:=№#\-–—]?\s*([^\n\r]+)/iu);
  if (explicit && explicit[1]) {
     const val = explicit[1].trim();
     // Проверяем, не является ли значение просто датой
     if (/^(?:вчера|сегодня|завтра)/i.test(val)) return null;
     return val;
  }

  const found = findValue(s, [
    /^\s*№\s*([^\n\r]+)$/iu,
    /^\s*([^\n\r]{1,80}?)\s+(?:от|дата)\b/iu
  ]);

  if (found && /^(?:вчера|сегодня|завтра)/i.test(found)) return null;
  return found;
}

function formatRuDate(d) {
  return d.toLocaleDateString('ru-RU', { timeZone: 'Europe/Moscow' });
}

function shiftedMoscowDate(days) {
  const now = new Date();
  const moscow = new Date(now.toLocaleString('en-US', { timeZone: 'Europe/Moscow' }));
  moscow.setDate(moscow.getDate() + days);
  return formatRuDate(moscow);
}

function parseContractDate(sourceText) {
  const s = String(sourceText || '').trim().toLowerCase();
  if (!s) return null;

  if (/\bсегодня(?:шн(?:ее|его)\s+числ[ао])?\b/iu.test(s)) return shiftedMoscowDate(0);
  if (/\bвчера(?:шн(?:ее|его)\s+числ[ао])?\b/iu.test(s)) return shiftedMoscowDate(-1);
  if (/\bзавтра(?:шн(?:ее|его)\s+числ[ао])?\b|\bзавтрашн(?:ее|его)\s+числ[ао]\b/iu.test(s)) return shiftedMoscowDate(1);

  const labeled = s.match(/(?:дата\s+договора|дата|от)\s*[:=\-–—]?\s*(\d{1,2})[.,\/\-\s](\d{1,2})[.,\/\-\s](\d{2,4})/iu);
  const anyDate = s.match(/\b(\d{1,2})[.,\/\-\s](\d{1,2})[.,\/\-\s](\d{2,4})\b/u);
  const m = labeled || anyDate;
  if (m) {
    const year = m[3].length === 2 ? `20${m[3]}` : m[3];
    return `${m[1].padStart(2, '0')}.${m[2].padStart(2, '0')}.${year}`;
  }

  return null;
}

function parseAmount(sourceText) {
  return findValue(sourceText, [
    /(?:сумма|стоимость|цена)\s*[:=\-–—]?\s*([0-9\s.,]+)/i
  ]);
}

function oneLineParam(value) {
  return value == null
    ? null
    : String(value)
        .replace(/[\u00a0\t]+/g, ' ')
        .replace(/\s+/g, ' ')
        .replace(/^[\s:：=\-–—]+|[\s;]+$/g, '')
        .trim() || null;
}

function findCustomParam(sourceText, labels) {
  const text = String(sourceText || '').replace(/\r/g, '\n');
  const lines = text.split('\n').map(l => l.trim()).filter(Boolean);

  for (const line of lines) {
    for (const label of labels) {
      const re = new RegExp('^\\s*(?:' + label + ')\\s*(?:[:：=]|[-–—])?\\s*(.+)$', 'iu');
      const m = line.match(re);
      if (m && m[1]) return oneLineParam(m[1]);
    }
  }

  return null;
}

function parseOptionalParams(sourceText) {
  const s = String(sourceText || '').trim();
  const out = {};

  const dateRaw = findCustomParam(s, [
    'дата\\s+договора',
    'договор\\s+от'
  ]);
  const onlyDate = /^(?:сегодня|вчера|завтра)(?:шн(?:ее|его)\s+числ[ао])?$/iu.test(s) || /^\d{1,2}[.,\/\-\s]\d{1,2}[.,\/\-\s]\d{2,4}$/u.test(s)
    ? s
    : null;
  const parsedDate = parseContractDate(dateRaw || onlyDate || '');
  if (parsedDate) out.contract_date = parsedDate;

  const paymentTerms = findCustomParam(s, [
    'условия\\s+оплаты',
    'порядок\\s+оплаты',
    'оплата'
  ]);
  if (paymentTerms) out.payment_terms = paymentTerms;

  const deliveryTerm = findCustomParam(s, [
    'срок\\s+поставки',
    'срок\\s+доставки',
    'поставка\\s+до',
    'дата\\s+поставки'
  ]);
  if (deliveryTerm) out.delivery_term = deliveryTerm;

  const deliveryConditions = findCustomParam(s, [
    'условия\\s+доставки',
    'условия\\s+поставки',
    'способ\\s+доставки',
    'доставка'
  ]);
  if (deliveryConditions) out.delivery_conditions = deliveryConditions;

  const contractEndRaw = findCustomParam(s, [
    'срок\\s+договора',
    'договор\\s+действует\\s+до',
    'действует\\s+до'
  ]);
  if (contractEndRaw) out.contract_end_date = parseContractDate(contractEndRaw) || oneLineParam(contractEndRaw);

  const penaltyRate = findCustomParam(s, [
    'штрафные\\s+санкции',
    'ставка\\s+штрафных\\s+санкций',
    'пеня',
    'неустойка'
  ]);
  if (penaltyRate) out.penalty_rate = penaltyRate;

  const customAmount = findCustomParam(s, [
    'сумма',
    'стоимость',
    'цена'
  ]);
  if (customAmount) out.amount = customAmount;

  return out;
}

function findCustomParam(sourceText, labels) {
  const text = String(sourceText || '').replace(/\r/g, '\n');
  const lines = text.split('\n').map(l => l.trim()).filter(Boolean);

  for (const line of lines) {
    for (const label of labels) {
      const re = new RegExp('^\\s*(?:' + label + ')\\s*(?:[:：=]|[-–—])?\\s*(.+)$', 'iu');
      const m = line.match(re);
      if (m && m[1]) return m[1].replace(/\s+/g, ' ').trim();
    }
  }

  return null;
}

function parseContractParams(sourceText) {
  return {
    payment_terms: findCustomParam(sourceText, ['условия\\s+оплаты', 'порядок\\s+оплаты', 'оплата']),
    delivery_term: findCustomParam(sourceText, ['срок\\s+поставки', 'срок\\s+доставки', 'поставка\\s+до', 'дата\\s+поставки']),
    delivery_conditions: findCustomParam(sourceText, ['условия\\s+доставки', 'условия\\s+поставки', 'способ\\s+доставки', 'доставка']),
    penalty_rate: findCustomParam(sourceText, ['штрафные\\s+санкции', 'ставка\\s+штрафных\\s+санкций', 'пеня', 'неустойка']),
    contract_end_date: findCustomParam(sourceText, ['срок\\s+договора', 'договор\\s+действует\\s+до', 'действует\\s+до'])
  };
}

function hasPayload(sess) {
  const saved = uniqJoin([
    sess.extracted_text,
    sess.message_text,
    sess.caption_text,
    sess.ocr_text
  ]);

  // Должен быть либо файл, либо значимый текст (не команда /start)
  const hasText = !!saved && saved.trim().length > 10 && !/^\/start/i.test(saved.trim());

  return !!sess.file_id || hasText;
}

function saveIncoming(sess) {
  const parsedType = parseContractType(rawText);
  const parsedFormat = parseOutputFormat(rawText);
  const parsedNumber = parseContractNumber(rawText);
  const parsedDate = parseContractDate(rawText);
  const parsedAmount = parseAmount(rawText);
  const parsedParams = parseContractParams(rawText);

  // Новый файл/фото вне режима досылки = новый контрагент/новый договор.
  // Оставляем только выбранный шаблон и формат, чтобы не тащить старые реквизиты,
  // старый номер и старую дату в следующий договор.
  // Любой новый файл/фото — это сигнал к обновлению реквизитов, 
  // если пользователь не находится в процессе подтверждения.
  const isNewMainFile = !!fileId && !sess.confirmed;

  const baseSess = isNewMainFile
    ? {
        contract_type: parsedType || sess.contract_type || null,
        output_format: parsedFormat || sess.output_format || null,
        chat_id: sess.chat_id,
        user_id: sess.user_id
      }
    : sess;

  const merged = isNewMainFile
    ? uniqJoin([rawText])
    : uniqJoin([
        sess.extracted_text,
        sess.message_text,
        sess.caption_text,
        sess.ocr_text,
        rawText
      ]);

  return {
    ...baseSess,
    input_type: fileId ? 'file' : (baseSess.input_type || inputType || 'text'),
    file_id: fileId || baseSess.file_id || null,
    file_name: fileName || baseSess.file_name || null,
    mime_type: mimeType || baseSess.mime_type || null,
    message_text: rawText || baseSess.message_text || '',
    caption_text: rawText || baseSess.caption_text || '',
    extracted_text: merged,
    ocr_text: isNewMainFile ? null : (baseSess.ocr_text || null),
    requisites: isNewMainFile ? {} : (baseSess.requisites || {}),
    contract_type: parsedType || baseSess.contract_type || null,
    output_format: parsedFormat || baseSess.output_format || null,
    // При новом файле сбрасываем номер и дату, если они не присланы вместе с ним
    contract_number: isNewMainFile ? (parsedNumber || null) : (parsedNumber || baseSess.contract_number || null),
    contract_date: isNewMainFile ? (parsedDate || null) : (parsedDate || baseSess.contract_date || null),
    amount: parsedAmount || baseSess.amount || null,
    payment_terms: parsedParams.payment_terms || baseSess.payment_terms || null,
    delivery_term: parsedParams.delivery_term || baseSess.delivery_term || null,
    delivery_conditions: parsedParams.delivery_conditions || baseSess.delivery_conditions || null,
    penalty_rate: parsedParams.penalty_rate || baseSess.penalty_rate || null,
    contract_end_date: parsedParams.contract_end_date || baseSess.contract_end_date || null,
    awaiting_supplement: false,
    awaiting_number: false,
    confirmed: false
  };
}

function output(sess, route) {
  const extracted = uniqJoin([
    sess.extracted_text,
    sess.message_text,
    sess.caption_text,
    sess.ocr_text
  ]);

  return [
    {
      json: {
        ...sess,
        ...BASE,

        chat_id: chatId,
        user_id: userId || null,
        session_keys: keys,
        route,

        input_type: sess.input_type || inputType,
        file_id: sess.file_id || fileId || null,
        file_name: sess.file_name || fileName || null,
        mime_type: sess.mime_type || mimeType || null,

        message_text: sess.message_text || rawText || '',
        caption_text: sess.caption_text || rawText || null,
        extracted_text: extracted,
        ocr_text: sess.ocr_text || null,

        contract_type: sess.contract_type || parseContractType(rawText) || null,
        output_format: sess.output_format || parseOutputFormat(rawText) || null,
        contract_number: sess.contract_number || parseContractNumber(rawText) || null,
        contract_date: sess.contract_date || parseContractDate(rawText) || null,
        amount: sess.amount || parseAmount(rawText) || null,
        payment_terms: sess.payment_terms || parseContractParams(rawText).payment_terms || null,
        delivery_term: sess.delivery_term || parseContractParams(rawText).delivery_term || null,
        delivery_conditions: sess.delivery_conditions || parseContractParams(rawText).delivery_conditions || null,
        penalty_rate: sess.penalty_rate || parseContractParams(rawText).penalty_rate || null,
        contract_end_date: sess.contract_end_date || parseContractParams(rawText).contract_end_date || null,

        confirmed: !!sess.confirmed,
        awaiting_supplement: !!sess.awaiting_supplement,
        awaiting_number: !!sess.awaiting_number
      }
    }
  ];
}



const PARAM_CHOICES = {
  payment: {
    standard: BASE.defaults.payment_terms,
    prepay100: 'Оплата за Товар осуществляется на условиях 100% предоплаты путём банковского перечисления на расчётный счёт Продавца.',
    prepay50: 'Оплата за Товар осуществляется на условиях 50% предоплаты, оставшиеся 50% оплачиваются Покупателем после уведомления о готовности Товара к отгрузке.',
    after: 'Оплата за Товар осуществляется Покупателем в течение 5 (пяти) банковских дней с даты поставки Товара.'
  },
  deliveryTerm: {
    standard: BASE.defaults.delivery_term,
    d10: '10 (десять) календарных дней с момента получения предоплаты по согласованному Счету.',
    d5work: '5 (пять) рабочих дней с момента получения предоплаты по согласованному Счету.',
    d30: '30 (тридцать) календарных дней с момента получения предоплаты по согласованному Счету.'
  },
  deliveryConditions: {
    standard: BASE.defaults.delivery_conditions,
    self: 'Покупатель осуществляет самовывоз Товара со склада Продавца.',
    supplier: 'Доставка Товара осуществляется силами Продавца до адреса Покупателя.',
    buyer: 'Доставка Товара осуществляется силами и за счёт Покупателя.',
    agreed: 'Поставка осуществляется на условиях, согласованных Сторонами.'
  },
  amount: {
    standard: BASE.defaults.default_amount,
    a2500000: '2500000'
  }
};

function todayMoscow() {
  return shiftedMoscowDate(0);
}

function updateParamsAndRoute(patch, route) {
  session = {
    ...session,
    ...patch,
    awaiting_optional_params: true,
    optional_params_done: false,
    confirmed: false,
    awaiting_supplement: false,
    awaiting_number: false
  };
  saveSession(session);
  return output(session, route);
}

function finishParams(patch = {}) {
  session = {
    ...session,
    ...patch,
    contract_date: patch.contract_date || session.contract_date || todayMoscow(),
    payment_terms: patch.payment_terms || session.payment_terms || BASE.defaults.payment_terms,
    delivery_term: patch.delivery_term || session.delivery_term || BASE.defaults.delivery_term,
    delivery_conditions: patch.delivery_conditions || session.delivery_conditions || BASE.defaults.delivery_conditions,
    amount: patch.amount || session.amount || BASE.defaults.default_amount,
    optional_params_done: true,
    awaiting_optional_params: false,
    confirmed: false,
    awaiting_supplement: false,
    awaiting_number: false
  };
  saveSession(session);
  return output(session, 'recheck');
}


// MAIN MENU CALLBACKS
if (callbackData === 'menu:create_contract') {
  clearSession();
  return output({}, 'menu_create');
}

if (callbackData === 'menu:analyze') {
  return output(session, 'menu_analyze');
}

if (callbackData === 'menu:check_codes') {
  return output(session, 'menu_check_codes');
}

// BITRIX CALLBACKS
if (callbackData === 'bitrix:create_task') {
  return output({ ...session, bitrix_step: 'ask_assignee' }, 'bitrix_ask_assignee');
}

if (callbackData === 'bitrix:skip') {
  return output(session, 'bitrix_skip');
}

if (callbackData.startsWith('bitrix:assignee:') || callbackData.startsWith('bitrix:deadline:') || callbackData === 'bitrix:confirmed') {
  const cbSession = { ...session, callback_data: callbackData };
  saveSession(cbSession);
  return output(cbSession, 'bitrix_process');
}

// AWAITING BITRIX CUSTOM DEADLINE
if (session.awaiting_bitrix_deadline) {
  const cbSession = { ...session, message_text: rawText };
  saveSession(cbSession);
  return output(cbSession, 'bitrix_process');
}

// START
if (
  /^\/start(?:@\w+)?$/i.test(String(rawText || '').trim()) ||
  callbackData === 'contract:start'
) {
  clearSession();
  return output({}, 'start');
}

// CANCEL
if (callbackData === 'contract:cancel') {
  clearSession();
  return output({}, 'cancelled');
}


// PARAMETER CHOICE: DATE
if (callbackData.startsWith('contract:param:date:')) {
  const value = callbackData.split(':').pop();

  if (value === 'custom') {
    session = {
      ...session,
      awaiting_custom_param: 'contract_date',
      awaiting_custom_param_label: 'дату договора',
      next_route_after_custom: 'ask_param_payment',
      awaiting_optional_params: true,
      optional_params_done: false,
      confirmed: false,
      awaiting_supplement: false,
      awaiting_number: false
    };
    saveSession(session);
    return output(session, 'ask_custom_param');
  }

  const selectedDate =
    value === 'yesterday' ? shiftedMoscowDate(-1) :
    value === 'tomorrow' ? shiftedMoscowDate(1) :
    shiftedMoscowDate(0);

  return updateParamsAndRoute({
    contract_date: selectedDate,
    param_date_choice: value
  }, 'ask_param_payment');
}

// PARAMETER CHOICE: PAYMENT TERMS
if (callbackData.startsWith('contract:param:payment:')) {
  const value = callbackData.split(':').pop();

  if (value === 'custom') {
    session = {
      ...session,
      awaiting_custom_param: 'payment_terms',
      awaiting_custom_param_label: 'условия оплаты',
      next_route_after_custom: 'ask_param_delivery_term',
      awaiting_optional_params: true,
      optional_params_done: false,
      confirmed: false,
      awaiting_supplement: false,
      awaiting_number: false
    };
    saveSession(session);
    return output(session, 'ask_custom_param');
  }

  const payment = PARAM_CHOICES.payment[value] || PARAM_CHOICES.payment.standard;

  return updateParamsAndRoute({
    payment_terms: payment,
    param_payment_choice: value
  }, 'ask_param_delivery_term');
}

// PARAMETER CHOICE: DELIVERY TERM
if (callbackData.startsWith('contract:param:delivery_term:')) {
  const value = callbackData.split(':').pop();

  if (value === 'custom') {
    session = {
      ...session,
      awaiting_custom_param: 'delivery_term',
      awaiting_custom_param_label: 'срок поставки',
