function rubWords(n) {
  const u = ['', 'один', 'два', 'три', 'четыре', 'пять', 'шесть', 'семь', 'восемь', 'девять'];
  const uf = ['', 'одна', 'две', 'три', 'четыре', 'пять', 'шесть', 'семь', 'восемь', 'девять'];
  const teen = ['десять', 'одиннадцать', 'двенадцать', 'тринадцать', 'четырнадцать', 'пятнадцать', 'шестнадцать', 'семнадцать', 'восемнадцать', 'девятнадцать'];
  const tens = ['', '', 'двадцать', 'тридцать', 'сорок', 'пятьдесят', 'шестьдесят', 'семьдесят', 'восемьдесят', 'девяносто'];
  const hun = ['', 'сто', 'двести', 'триста', 'четыреста', 'пятьсот', 'шестьсот', 'семьсот', 'восемьсот', 'девятьсот'];

  function tri(x, f = false) {
    const a = [];
    const h = Math.floor(x / 100);
    const t = Math.floor((x % 100) / 10);
    const d = x % 10;

    if (h) a.push(hun[h]);

    if (t === 1) {
      a.push(teen[d]);
    } else {
      if (t) a.push(tens[t]);
      if (d) a.push((f ? uf : u)[d]);
    }

    return a.join(' ');
  }

  function form(x, a, b, c) {
    const n10 = x % 10;
    const n100 = x % 100;

    if (n10 === 1 && n100 !== 11) return a;
    if ([2, 3, 4].includes(n10) && ![12, 13, 14].includes(n100)) return b;

    return c;
  }

  const out = [];
  const mil = Math.floor(n / 1000000);
  const th = Math.floor((n % 1000000) / 1000);
  const rest = n % 1000;

  if (mil) out.push(tri(mil), form(mil, 'миллион', 'миллиона', 'миллионов'));
  if (th) out.push(tri(th, true), form(th, 'тысяча', 'тысячи', 'тысяч'));
  if (rest) out.push(tri(rest));
  if (!out.length) out.push('ноль');

  // Ничего не добавляем — только сумма прописью

  return out.join(' ');
}

