function oneLineParam(value) {
  return value == null
    ? null
    : String(value)
        .replace(/[\u00a0\t]+/g, ' ')
        .replace(/\s+/g, ' ')
        .replace(/^[\s:：=\-–—]+|[\s;]+$/g, '')
        .trim() || null;
}

function findCustomParam(sourceText, labels) {
  const text = String(sourceText || '').replace(/\r/g, '\n');
  const lines = text.split('\n').map(l => l.trim()).filter(Boolean);

  for (const line of lines) {
    for (const label of labels) {
      const re = new RegExp('^\\s*(?:' + label + ')\\s*(?:[:：=]|[-–—])?\\s*(.+)$', 'iu');
      const m = line.match(re);
      if (m && m[1]) return oneLineParam(m[1]);
    }
  }

  const flat = text.replace(/\s+/g, ' ').trim();
  for (const label of labels) {
    const re = new RegExp('(?:' + label + ')\\s*(?:[:：=]|[-–—])?\\s*(.+?)(?=\\s+(?:дата\\s+договора|срок\\s+поставки|условия\\s+оплаты|порядок\\s+оплаты|условия\\s+доставки|условия\\s+поставки|срок\\s+договора|договор\\s+действует\\s+до|штраф|пеня|неустойка|сумма|стоимость|цена)\\s*(?:[:：=]|[-–—])|$)', 'iu');
    const m = flat.match(re);
    if (m && m[1]) return oneLineParam(m[1]);
  }

  return null;
}

function formatRuDateObj(d) {
  return d.toLocaleDateString('ru-RU', { timeZone: 'Europe/Moscow' });
}

function shiftedMoscowDate(days) {
  const now = new Date();
  const moscow = new Date(now.toLocaleString('en-US', { timeZone: 'Europe/Moscow' }));
  moscow.setDate(moscow.getDate() + days);
  return formatRuDateObj(moscow);
}

function normalizeRuDate(value) {
  const s = String(value || '').trim().toLowerCase();
  if (!s) return null;

  if (/^сегодня(?:шн(?:ее|его)\s+числ[ао])?$/iu.test(s)) return shiftedMoscowDate(0);
  if (/^вчера(?:шн(?:ее|его)\s+числ[ао])?$/iu.test(s)) return shiftedMoscowDate(-1);
  if (/^завтра(?:шн(?:ее|его)\s+числ[ао])?$|^завтрашн(?:ее|его)\s+числ[ао]$/iu.test(s)) return shiftedMoscowDate(1);

  const m = s.match(/\b(\d{1,2})[.,\/\-\s](\d{1,2})[.,\/\-\s](\d{2,4})\b/u);
  if (m) {
    const year = m[3].length === 2 ? `20${m[3]}` : m[3];
    return `${m[1].padStart(2, '0')}.${m[2].padStart(2, '0')}.${year}`;
  }

  return oneLineParam(value);
}

// Дополнительные параметры парсим только из специального текста,
// который пользователь прислал в ответ на шаг "дополнительные параметры".
// Не парсим OCR/старый message_text, иначе дата может случайно стать огромным куском договора.
