]);

const userOnlyDateRaw = (() => {
  const s = String($json.message_text || $json.caption_text || '').trim();
  if (/^(?:сегодня|вчера|завтра)(?:шн(?:ее|его)\s+числ[ао])?$/iu.test(s)) return s;
  if (/^\d{1,2}[.,\/\-\s]\d{1,2}[.,\/\-\s]\d{2,4}$/u.test(s)) return s;
  return null;
})();

const customContractDate = normalizeRuDate(customContractDateRaw || userOnlyDateRaw);

