function addDocControlWarnings(source) {
  const text = String(source || '').replace(/\s+/g, ' ').trim();

  if (!text) {
    warnings.push('Не удалось проверить подписи, печати и штампы: нет распознанного текста документа.');
    return;
  }

  const lower = text.toLowerCase();

  const isCmr = /\bcmr\b|цмр|международн(?:ая|ой)\s+товарно-транспортн/i.test(lower);
  const isUpd = /\bупд\b|универсальн(?:ый|ого)\s+передаточн/i.test(lower);
  const isSpec = /спецификац/i.test(lower);
  const isContract = /договор/i.test(lower);

  const hasSignature = hasAny(lower, [/подпис/i, /подпись/i, /м\.?\s*п\.?/i]);
  const hasSeal = hasAny(lower, [/печать/i, /штамп/i, /м\.?\s*п\.?/i]);

  if (isContract || isSpec) {
    if (!hasAny(lower, [/номер/i, /№/i]) || !hasAny(lower, [/дата/i, /\d{2}\.\d{2}\.\d{4}/])) {
      warnings.push('Проверка договора/спецификации: не найден обязательный номер или дата документа.');
    }

    if (!hasSignature || !hasSeal) {
      warnings.push('Проверка договора/спецификации: проверьте наличие подписи и печати продавца и покупателя.');
    }
  }

  if (isCmr) {
    const cmrRules = [
      ['CMR графа 3: место разгрузки должно содержать город и страну.', /(?:графа\s*)?3|место\s+разгруз/i],
      ['CMR графа 4: место погрузки должно содержать город, страну и дату погрузки.', /(?:графа\s*)?4|место\s+погруз/i],
      ['CMR графа 5: должны быть номер и дата УПД.', /(?:графа\s*)?5|упд/i],
      ['CMR графа 16: должны быть штамп, печать или реквизиты перевозчика.', /(?:графа\s*)?16|перевозчик/i],
      ['CMR графа 21: обязательна дата составления.', /(?:графа\s*)?21|дата\s+состав/i],
      ['CMR графа 22: нужны подпись и печать отправителя.', /(?:графа\s*)?22|отправител/i],
