  const local = entry.localHeaderOffset;
  if (buffer.readUInt32LE(local) !== 0x04034b50) {
    throw new Error('Некорректный ZIP local header в DOCX');
  }

  const nameLen = buffer.readUInt16LE(local + 26);
  const extraLen = buffer.readUInt16LE(local + 28);
  const dataStart = local + 30 + nameLen + extraLen;
  const compressed = buffer.slice(dataStart, dataStart + entry.compressedSize);

  if (entry.method === 0) return compressed;
  if (entry.method === 8) return await inflateRawWithWebStream(compressed);

  throw new Error('Неподдерживаемый метод сжатия DOCX: ' + entry.method);
}

async function docxToText(buffer) {
  const documentXml = await readZipEntry(buffer, 'word/document.xml');
  if (!documentXml) throw new Error('В DOCX не найден word/document.xml');

  const xml = documentXml.toString('utf8');

  return decodeXmlEntities(xml)
    .replace(/<w:tab\s*\/>/g, '\t')
    .replace(/<w:br\s*\/>/g, '\n')
    .replace(/<\/w:p>/g, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

try {
  const key = binaryKeys.includes('data') ? 'data' : binaryKeys[0];

  if (!key) {
    readError = 'Нет binary.data после Telegram Get File. В узле Telegram Get File включите Download = true.';
  } else {
    const buffer = await this.helpers.getBinaryDataBuffer(0, key);

    const isDocx = mime.includes('wordprocessingml.document') || fileName.endsWith('.docx');
    const isTxt = mime.includes('text/plain') || fileName.endsWith('.txt');

    if (isDocx) {
      fileText = await docxToText(buffer);
    } else if (isTxt) {
      fileText = buffer.toString('utf8');

      if ((fileText.match(/�/g) || []).length > 3 && typeof TextDecoder !== 'undefined') {
        try {
          fileText = new TextDecoder('windows-1251').decode(buffer);
        } catch (e) {}
      }
    } else {
      readError = 'Этот узел читает только TXT и DOCX. Для изображений/PDF используйте OCR ветку.';
    }
  }
} catch (e) {
  readError = e.message || String(e);
}

fileText = String(fileText || '')
  .replace(/^\uFEFF/, '')
  .replace(/\r\n/g, '\n')
  .replace(/\r/g, '\n')
  .trim();

function uniqJoin(values) {
  const seen = new Set();
  const out = [];
  for (const v of values) {
    const s = String(v || '').trim();
    if (!s || seen.has(s)) continue;
    seen.add(s);
    out.push(s);
  }
  return out.join('\n');
}

const mergedText = uniqJoin([
  original.extracted_text,
  original.message_text,
  original.caption_text,
  original.ocr_text,
  fileText
]);

return [{
  json: {
    ...original,
    message_text: original.message_text || '',
    caption_text: original.caption_text || original.message_text || '',
    extracted_text: mergedText,
    ocr_text: fileText || original.ocr_text || '',
    txt_read_ok: !!fileText,
    txt_read_error: readError,
    binary_keys_seen: binaryKeys,
    file_read_method: fileName.endsWith('.docx') || mime.includes('wordprocessingml.document') ? 'docx-web-decompression' : 'txt-buffer'
  }
}];

const source = $json;

function parseMaybeJson(value) {
  if (!value) return null;
  if (typeof value === 'object') return value;
  let text = String(value).trim();
  text = text.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/i, '').trim();
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start >= 0 && end > start) text = text.slice(start, end + 1);
  try { return JSON.parse(text); } catch (e) { return null; }
}

const agentPayload = parseMaybeJson(source.output || source.text || source.response || source.result);
const requisites = agentPayload?.requisites || null;

return [{
  json: {
    ...source,
    chatgpt_agent_used: true,
    chatgpt_agent_raw: source.output || source.text || source.response || source.result || null,
    chatgpt_agent_parsed: agentPayload,
    requisites: requisites || source.requisites || null,
    contract_number: source.contract_number || agentPayload?.contract_number || null,
    amount: source.amount || agentPayload?.amount || null
  }
}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};
const sessions = staticData.sessions;

const _normJson = $('Normalize Telegram Input').item.json;
const _chatId = String(_normJson.chat_id || '');
const original = { ...(sessions[_chatId] || {}), ..._normJson };


const item = $input.first();

if (!item.binary || !item.binary.data) {
  throw new Error('DOCX file was routed here, but binary.data is missing');
}

// DOCX is a ZIP archive. n8n Compression node requires fileExtension = zip.
item.binary.data.fileName = 'input.zip';
item.binary.data.fileExtension = 'zip';
item.binary.data.mimeType = 'application/zip';

return [{
  json: {
    ...original,
    ...item.json,
    docx_prepare_ok: true
  },
  binary: item.binary
}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};
const sessions = staticData.sessions;

const _normJson = $('Normalize Telegram Input').item.json;
const _chatId = String(_normJson.chat_id || '');
const original = { ...(sessions[_chatId] || {}), ..._normJson };

function decodeXmlEntities(s) {
  return String(s || '')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
    .replace(/&#x([0-9a-fA-F]+);/g, (_, n) => String.fromCharCode(parseInt(n, 16)));
}

function xmlToText(xml) {
  return decodeXmlEntities(
    String(xml || '')
      .replace(/<w:tab\s*\/>/g, '\t')
      .replace(/<w:br\s*\/>/g, '\n')
      .replace(/<\/w:p>/g, '\n')
      .replace(/<\/w:tr>/g, '\n')
      .replace(/<[^>]+>/g, '')
  )
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const keys = Object.keys($binary || {});

const fileNames = keys.map(k => ({
  key: k,
  fileName: $binary[k]?.fileName || '',
  mimeType: $binary[k]?.mimeType || ''
}));

let xml = '';
let foundKey = null;

// Сначала ищем по имени файла
for (const key of keys) {
  const meta = $binary[key] || {};
  const fileName = String(meta.fileName || '').replace(/\\/g, '/').toLowerCase();
  if (
    fileName === 'word/document.xml' ||
    fileName.endsWith('/word/document.xml') ||
    fileName.includes('document.xml')
  ) {
    try {
      const buffer = await this.helpers.getBinaryDataBuffer(0, key);
      const text = buffer.toString('utf8');
      if (text.includes('<w:') || text.includes('w:body')) {
        xml = text;
        foundKey = key;
        break;
      }
    } catch(e) {}
  }
}

// Если не нашли — перебираем все файлы и ищем Word XML
if (!xml) {
  for (const key of keys) {
    try {
      const buffer = await this.helpers.getBinaryDataBuffer(0, key);
      const text = buffer.toString('utf8');
      if (text.includes('<w:body') || text.includes('<w:document')) {
        xml = text;
        foundKey = key;
        break;
      }
    } catch(e) {}
  }
}

const docxText = xmlToText(xml);

return [{
  json: {
    ...original,
    extracted_text: docxText,
    ocr_text: docxText,
    file_read_ok: !!docxText,
    docx_read_ok: !!docxText,
    docx_binary_keys_seen: fileNames,
    docx_found_key: foundKey,
    docx_read_error: docxText ? null : 'Не найден word/document.xml. Файлы: ' + JSON.stringify(fileNames)
  }
}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};
const sessions = staticData.sessions;

const _normJson = $('Normalize Telegram Input').item.json;
const _chatId = String(_normJson.chat_id || '');
const original = { ...(sessions[_chatId] || {}), ..._normJson };


if (!$binary || !$binary.data) {
  throw new Error('TXT file was routed here, but binary.data is missing');
}

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
let txt = buffer.toString('utf8');

// Handle UTF-8 BOM
txt = txt.replace(/^\uFEFF/, '').trim();

return [{
  json: {
    ...original,
    extracted_text: txt,
    ocr_text: txt,
    file_read_ok: !!txt,
    txt_read_ok: !!txt,
    txt_read_error: txt ? null : 'TXT file is empty'
  }
}];

const staticData = $getWorkflowStaticData('global');

if (!$json.replacements || !$json.template_id || !$json.copy_name) {
  throw new Error('Save Contract Before Copy: на входе нет replacements/template_id/copy_name. Узел должен получать данные только после Validate And Build Replacements.');
}

if (!staticData.pending_contracts) {
  staticData.pending_contracts = {};
}

const chatId = String($json.chat_id || '');
const userId = $json.user_id ? `user:${$json.user_id}` : null;

staticData.pending_contracts[chatId] = $json;

if (userId) {
  staticData.pending_contracts[userId] = $json;
}

// также сохраняем последний валидный договор для одиночного пользователя/ручного запуска
staticData.pending_contract = $json;

return [{ json: $json }];

const fs = require('fs');
const SESSION_FILE = '/tmp/contract_bot_sessions.json';
const staticData = $getWorkflowStaticData('global');

function readFileSessions() {
  try {
    return JSON.parse(fs.readFileSync(SESSION_FILE, 'utf8'));
  } catch (e) {
    return {};
  }
}

function writeFileSessions(s) {
  try {
    fs.writeFileSync(SESSION_FILE, JSON.stringify(s), 'utf8');
  } catch (e) {}
}

let original = {};
try {
  original = $('Set Output File Name').item.json || {};
} catch (e) {
  original = {};
}

const chatId = String($json.chat_id || original.chat_id || '');
const userId = $json.user_id || original.user_id || null;
const sessionKeys =
  ($json.session_keys && $json.session_keys.length)
    ? $json.session_keys
    : (original.session_keys && original.session_keys.length)
      ? original.session_keys
      : [chatId, userId ? `user:${userId}` : null].filter(Boolean);

if (!staticData.sessions) staticData.sessions = {};

for (const key of sessionKeys) {
  delete staticData.sessions[String(key)];
}

const fileSessions = readFileSessions();
for (const key of sessionKeys) {
  delete fileSessions[String(key)];
}
writeFileSessions(fileSessions);

return [{
  json: {
    ...original,
    ...$json,
    chat_id: chatId,
    user_id: userId,
    session_keys: sessionKeys,
    session_cleared: true
  },
  binary: $binary
}];

