const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};
const chatId = String($json.chat_id || '');
const session = staticData.sessions[chatId] || {};

const callbackData = $json.callback_data || '';

// CONFIRMED - create task
if (callbackData === 'bitrix:confirmed') {
  const updated = { ...session, bitrix_confirmed: true };
  staticData.sessions[chatId] = updated;
  return [{ json: { ...updated, chat_id: chatId, route: 'bitrix_create' } }];
}

// ASSIGNEE SELECTED
if (callbackData.startsWith('bitrix:assignee:')) {
  const userId = callbackData.split(':').pop();
  const names = { '1': 'Себе', '2': 'Employee A', '3': 'Employee B', '4': 'Employee C' };
  const updated = {
    ...session,
    bitrix_assignee_id: userId,
    bitrix_assignee_name: names[userId] || userId,
    awaiting_bitrix_deadline: false,
    bitrix_step: 'ask_deadline'
  };
  staticData.sessions[chatId] = updated;
  return [{ json: { ...updated, chat_id: chatId, route: 'bitrix_ask_deadline' } }];
}

// DEADLINE SELECTED
if (callbackData.startsWith('bitrix:deadline:')) {
  const value = callbackData.split(':').pop();
  let deadline = null;

  if (value === 'contract_end') {
    deadline = session.contract_end_date || session.contract_date || null;
  } else if (value === '3d') {
    const d = new Date(); d.setDate(d.getDate() + 3);
    deadline = d.toISOString().split('T')[0];
  } else if (value === '7d') {
    const d = new Date(); d.setDate(d.getDate() + 7);
    deadline = d.toISOString().split('T')[0];
  } else if (value === 'custom') {
    const updated = { ...session, awaiting_bitrix_deadline: true, bitrix_step: 'await_deadline' };
    staticData.sessions[chatId] = updated;
    return [{ json: { ...updated, chat_id: chatId, route: 'bitrix_await_deadline' } }];
  }

  const updated = { ...session, bitrix_deadline: deadline, awaiting_bitrix_deadline: false, bitrix_step: 'confirm' };
  staticData.sessions[chatId] = updated;
  return [{ json: { ...updated, chat_id: chatId, route: 'bitrix_confirm' } }];
}

// CUSTOM DEADLINE TEXT INPUT
if (session.awaiting_bitrix_deadline) {
  const text = $json.message_text || '';
  const match = text.match(/(\d{1,2})\.(\d{1,2})\.(\d{4})/);
  let deadline = null;
  if (match) {
    deadline = `${match[3]}-${match[2].padStart(2,'0')}-${match[1].padStart(2,'0')}`;
  }
  const updated = { ...session, bitrix_deadline: deadline || text, awaiting_bitrix_deadline: false, bitrix_step: 'confirm' };
  staticData.sessions[chatId] = updated;
  return [{ json: { ...updated, chat_id: chatId, route: 'bitrix_confirm' } }];
}

return [{ json: { ...$json, route: 'unknown' } }];

